#include <stddef.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_STADI = 16;
constexpr size_t MAX_DATI = 32;

typedef double (*trasforma_fn)(double);

typedef struct stadio {
    char nome[24];
    trasforma_fn fn;
} stadio_t;

double raddoppia(double x) { return 2.0 * x; }
double dimezza(double x) { return 0.5 * x; }
double opposto(double x) { return (x == 0.0) ? 0.0 : -x; }
double satura(double x) {
    if (x < -1.0) { return -1.0; }
    if (x > 1.0) { return 1.0; }
    return x;
}

trasforma_fn risolvi_filtro(const char *nome) {
    if (nome == nullptr) { return nullptr; }
    if (strcmp(nome, "raddoppia") == 0) { return raddoppia; }
    if (strcmp(nome, "dimezza") == 0) { return dimezza; }
    if (strcmp(nome, "opposto") == 0) { return opposto; }
    if (strcmp(nome, "satura") == 0) { return satura; }
    return nullptr;
}

bool applica_pipeline(const stadio_t *stadi, size_t num_stadi, double *valori, size_t n) {
    if ((num_stadi > 0 && stadi == nullptr) || (n > 0 && valori == nullptr)) { return false; }
    for (size_t i = 0; i < num_stadi; ++i) {
        if (stadi[i].fn == nullptr) { return false; }
    }
    for (size_t j = 0; j < n; ++j) {
        for (size_t i = 0; i < num_stadi; ++i) {
            valori[j] = stadi[i].fn(valori[j]);
        }
    }
    return true;
}

int main(void) {
    char riga[512], extra = '\0';
    int k_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &k_in, &extra) != 1 || k_in < 0 || (size_t)k_in > MAX_STADI) {
        fprintf(stderr, "Errore: numero di stadi non valido.\n");
        return EXIT_FAILURE;
    }
    stadio_t stadi[MAX_STADI] = {};
    size_t num_stadi = 0;
    for (int i = 0; i < k_in; ++i) {
        char nome[24];
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%23s %c", nome, &extra) != 1) {
            fprintf(stderr, "Errore: nome filtro mancante.\n");
            return EXIT_FAILURE;
        }
        trasforma_fn fn = risolvi_filtro(nome);
        if (fn == nullptr) {
            printf("Filtro sconosciuto: %s\n", nome);
        } else {
            snprintf(stadi[num_stadi].nome, sizeof(stadi[num_stadi].nome), "%s", nome);
            stadi[num_stadi].fn = fn;
            ++num_stadi;
        }
    }
    int n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 0 || (size_t)n_in > MAX_DATI) {
        fprintf(stderr, "Errore: numero di dati non valido.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    double orig[MAX_DATI] = {}, ris[MAX_DATI] = {};
    if (n > 0) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
            fprintf(stderr, "Errore: riga dei dati mancante.\n");
            return EXIT_FAILURE;
        }
        const char *p = riga;
        for (size_t j = 0; j < n; ++j) {
            int letti = 0;
            if (sscanf(p, "%lf%n", &orig[j], &letti) != 1) {
                fprintf(stderr, "Errore: valore numerico non valido.\n");
                return EXIT_FAILURE;
            }
            ris[j] = orig[j];
            p += letti;
        }
        if (sscanf(p, " %c", &extra) == 1) {
            fprintf(stderr, "Errore: dati in eccesso.\n");
            return EXIT_FAILURE;
        }
    }
    if (!applica_pipeline(stadi, num_stadi, ris, n)) {
        fprintf(stderr, "Errore: pipeline non valida.\n");
        return EXIT_FAILURE;
    }
    printf("Pipeline (%zu stadi): ", num_stadi);
    if (num_stadi == 0) {
        printf("(vuota)\n");
    } else {
        for (size_t i = 0; i < num_stadi; ++i) {
            printf("%s%s", (i > 0) ? " -> " : "", stadi[i].nome);
        }
        printf("\n");
    }
    if (n == 0) {
        printf("Nessun dato.\n");
    } else {
        for (size_t j = 0; j < n; ++j) {
            printf("val[%zu]: %.2f -> %.2f\n", j, orig[j], ris[j]);
        }
    }
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_ELEM = 32;

typedef bool (*predicato_fn)(const void *elem, const void *ctx);
typedef void (*accumula_fn)(void *acc, const void *elem, const void *ctx);

typedef struct intervallo { int32_t min; int32_t max; } intervallo_t;
typedef struct stat_int { int64_t somma; int32_t max; bool presente; } stat_int_t;
typedef struct esame { char codice[16]; int voto; int crediti; } esame_t;
typedef struct stat_esami { int64_t somma_pesata; int64_t tot_crediti; } stat_esami_t;

size_t filtra_generico(const void *src, size_t n, size_t dim_elem, void *dst,
                       predicato_fn pred, const void *ctx) {
    if (pred == nullptr || dim_elem == 0 || n == 0 || src == nullptr || dst == nullptr) {
        return 0;
    }
    const unsigned char *s = src;
    unsigned char *d = dst;
    size_t scritti = 0;
    for (size_t i = 0; i < n; ++i) {
        const void *e = s + i * dim_elem;
        if (pred(e, ctx)) {
            memcpy(d + scritti * dim_elem, e, dim_elem);
            ++scritti;
        }
    }
    return scritti;
}

bool riduci_generico(const void *src, size_t n, size_t dim_elem, void *acc,
                     accumula_fn fn, const void *ctx) {
    if (acc == nullptr || fn == nullptr || dim_elem == 0 || (n > 0 && src == nullptr)) {
        return false;
    }
    const unsigned char *s = src;
    for (size_t i = 0; i < n; ++i) {
        fn(acc, s + i * dim_elem, ctx);
    }
    return true;
}

bool pred_in_intervallo(const void *elem, const void *ctx) {
    const int32_t *val = elem;
    const intervallo_t *iv = ctx;
    return *val >= iv->min && *val <= iv->max;
}

void acc_stat_int(void *acc, const void *elem, const void *ctx) {
    (void)ctx;
    stat_int_t *st = acc;
    const int32_t *val = elem;
    st->somma += *val;
    if (!st->presente || *val > st->max) {
        st->max = *val;
        st->presente = true;
    }
}

bool pred_voto_almeno(const void *elem, const void *ctx) {
    const esame_t *es = elem;
    const int *soglia = ctx;
    return es->voto >= *soglia;
}

void acc_stat_esami(void *acc, const void *elem, const void *ctx) {
    (void)ctx;
    stat_esami_t *st = acc;
    const esame_t *es = elem;
    st->somma_pesata += (int64_t)es->voto * (int64_t)es->crediti;
    st->tot_crediti += (int64_t)es->crediti;
}

int main(void) {
    char riga[512], extra = '\0';
    int n_int_in = 0;
    long long min_in = 0, max_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %lld %lld %c", &n_int_in, &min_in, &max_in, &extra) != 3 ||
        n_int_in < 0 || (size_t)n_int_in > MAX_ELEM ||
        min_in < INT32_MIN || max_in > INT32_MAX || min_in > max_in) {
        fprintf(stderr, "Errore: intestazione interi non valida.\n");
        return EXIT_FAILURE;
    }
    size_t n_int = (size_t)n_int_in;
    int32_t numeri[MAX_ELEM] = {}, num_filt[MAX_ELEM] = {};
    if (n_int > 0) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) { return EXIT_FAILURE; }
        const char *p = riga;
        for (size_t i = 0; i < n_int; ++i) {
            long long v = 0;
            int letti = 0;
            if (sscanf(p, "%lld%n", &v, &letti) != 1 || v < INT32_MIN || v > INT32_MAX) {
                return EXIT_FAILURE;
            }
            numeri[i] = (int32_t)v;
            p += letti;
        }
        if (sscanf(p, " %c", &extra) == 1) { return EXIT_FAILURE; }
    }
    int n_es_in = 0, voto_min = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %d %c", &n_es_in, &voto_min, &extra) != 2 ||
        n_es_in < 0 || (size_t)n_es_in > MAX_ELEM) {
        fprintf(stderr, "Errore: intestazione esami non valida.\n");
        return EXIT_FAILURE;
    }
    size_t n_es = (size_t)n_es_in;
    esame_t esami[MAX_ELEM] = {}, es_filt[MAX_ELEM] = {};
    for (size_t i = 0; i < n_es; ++i) {
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%15s %d %d %c", esami[i].codice, &esami[i].voto, &esami[i].crediti, &extra) != 3 ||
            esami[i].crediti < 0) {
            return EXIT_FAILURE;
        }
    }
    intervallo_t iv = {.min = (int32_t)min_in, .max = (int32_t)max_in};
    size_t k_int = filtra_generico(numeri, n_int, sizeof(int32_t), num_filt, pred_in_intervallo, &iv);
    stat_int_t st_int = {};
    riduci_generico(num_filt, k_int, sizeof(int32_t), &st_int, acc_stat_int, nullptr);
    size_t k_es = filtra_generico(esami, n_es, sizeof(esame_t), es_filt, pred_voto_almeno, &voto_min);
    stat_esami_t st_es = {};
    riduci_generico(es_filt, k_es, sizeof(esame_t), &st_es, acc_stat_esami, nullptr);

    printf("Interi filtrati (%zu):", k_int);
    if (k_int == 0) { printf(" (nessuno)\n"); }
    else {
        for (size_t i = 0; i < k_int; ++i) { printf(" %" PRId32, num_filt[i]); }
        printf("\n");
    }
    if (st_int.presente) {
        printf("Stat interi: somma=%" PRId64 " max=%" PRId32 "\n", st_int.somma, st_int.max);
    } else {
        printf("Stat interi: nessun dato\n");
    }
    printf("Esami filtrati (%zu):", k_es);
    if (k_es == 0) { printf(" (nessuno)\n"); }
    else {
        for (size_t i = 0; i < k_es; ++i) { printf(" %s(%d)", es_filt[i].codice, es_filt[i].voto); }
        printf("\n");
    }
    double media = (st_es.tot_crediti > 0) ? ((double)st_es.somma_pesata / (double)st_es.tot_crediti) : 0.0;
    printf("Stat esami: crediti=%" PRId64 " media=%.2f\n", st_es.tot_crediti, media);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr size_t MAX_LIBRI = 64;
constexpr size_t MAX_QUERY = 16;

typedef struct libro {
    int32_t codice;
    char titolo[32];
    int32_t anno;
    int32_t pagine;
} libro_t;

int cmp_i32(int32_t x, int32_t y) { return (x > y) - (x < y); }

int cmp_per_anno_pagine(const void *a, const void *b) {
    const libro_t *la = a;
    const libro_t *lb = b;
    int r = cmp_i32(la->anno, lb->anno);
    if (r != 0) { return r; }
    r = cmp_i32(lb->pagine, la->pagine);
    if (r != 0) { return r; }
    return cmp_i32(la->codice, lb->codice);
}

int cmp_per_titolo(const void *a, const void *b) {
    const libro_t *la = a;
    const libro_t *lb = b;
    int r = strcmp(la->titolo, lb->titolo);
    if (r != 0) { return r; }
    return cmp_i32(la->codice, lb->codice);
}

int cmp_per_codice(const void *a, const void *b) {
    const libro_t *la = a;
    const libro_t *lb = b;
    return cmp_i32(la->codice, lb->codice);
}

void stampa_catalogo(const char *intestazione, const libro_t *cat, size_t n) {
    printf("%s\n", intestazione);
    if (n == 0) {
        printf("  (vuoto)\n");
        return;
    }
    for (size_t i = 0; i < n; ++i) {
        printf("  [#%" PRId32 "] %s (%" PRId32 ", %" PRId32 " pag)\n",
               cat[i].codice, cat[i].titolo, cat[i].anno, cat[i].pagine);
    }
}

int main(void) {
    char riga[256], extra = '\0';
    int n_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n_in, &extra) != 1 || n_in < 0 || (size_t)n_in > MAX_LIBRI) {
        fprintf(stderr, "Errore: numero di libri non valido.\n");
        return EXIT_FAILURE;
    }
    size_t n = (size_t)n_in;
    libro_t *catalogo = (n > 0) ? calloc(n, sizeof(*catalogo)) : nullptr;
    if (n > 0 && catalogo == nullptr) {
        fprintf(stderr, "Errore: memoria esaurita.\n");
        return EXIT_FAILURE;
    }
    for (size_t i = 0; i < n; ++i) {
        long long cod = 0, anno = 0, pag = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%lld %31s %lld %lld %c", &cod, catalogo[i].titolo, &anno, &pag, &extra) != 4 ||
            cod < INT32_MIN || cod > INT32_MAX || anno < INT32_MIN || anno > INT32_MAX ||
            pag < 0 || pag > INT32_MAX) {
            free(catalogo);
            fprintf(stderr, "Errore: dati libro non validi.\n");
            return EXIT_FAILURE;
        }
        catalogo[i].codice = (int32_t)cod;
        catalogo[i].anno = (int32_t)anno;
        catalogo[i].pagine = (int32_t)pag;
    }
    int q_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &q_in, &extra) != 1 || q_in < 0 || (size_t)q_in > MAX_QUERY) {
        free(catalogo);
        fprintf(stderr, "Errore: numero di query non valido.\n");
        return EXIT_FAILURE;
    }
    int32_t query[MAX_QUERY] = {};
    size_t q = (size_t)q_in;
    for (size_t i = 0; i < q; ++i) {
        long long cod = 0;
        if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
            sscanf(riga, "%lld %c", &cod, &extra) != 1 || cod < INT32_MIN || cod > INT32_MAX) {
            free(catalogo);
            fprintf(stderr, "Errore: codice query non valido.\n");
            return EXIT_FAILURE;
        }
        query[i] = (int32_t)cod;
    }
    if (n > 0) { qsort(catalogo, n, sizeof(*catalogo), cmp_per_anno_pagine); }
    stampa_catalogo("Ordinati per anno/pagine:", catalogo, n);
    if (n > 0) { qsort(catalogo, n, sizeof(*catalogo), cmp_per_titolo); }
    stampa_catalogo("Ordinati per titolo:", catalogo, n);
    if (n > 0) { qsort(catalogo, n, sizeof(*catalogo), cmp_per_codice); }
    const libro_t *vista = catalogo;
    for (size_t i = 0; i < q; ++i) {
        const libro_t *trovato = nullptr;
        if (n > 0) {
            libro_t chiave = {.codice = query[i]};
            trovato = bsearch(&chiave, vista, n, sizeof(*vista), cmp_per_codice);
        }
        if (trovato != nullptr) {
            printf("Cerca %" PRId32 ": TROVATO %s (%" PRId32 ", %" PRId32 " pag)\n",
                   query[i], trovato->titolo, trovato->anno, trovato->pagine);
        } else {
            printf("Cerca %" PRId32 ": NON TROVATO\n", query[i]);
        }
    }
    free(catalogo);
    return EXIT_SUCCESS;
}

#include <inttypes.h>
#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

constexpr int NUM_REG = 4;

typedef struct macchina {
    int64_t reg[NUM_REG];
    size_t ops_eseguite;
} macchina_t;

typedef bool (*comando_fn)(macchina_t *m, const char *args);
typedef struct voce_cmd {
    const char *nome;
    comando_fn esegui;
} voce_cmd_t;

typedef enum formato_out {
    FMT_DEC = 0,
    FMT_HEX = 1,
    FMT_SOMMA = 2,
    FMT_CONTEGGIO = 3
} formato_out_t;

typedef void (*stampa_fn)(const macchina_t *m);

bool reg_valido(int r) { return r >= 0 && r < NUM_REG; }

bool cmd_add(macchina_t *m, const char *args) {
    int d = 0, s = 0; char extra = '\0';
    if (sscanf(args, "%d %d %c", &d, &s, &extra) != 2 || !reg_valido(d) || !reg_valido(s)) { return false; }
    m->reg[d] += m->reg[s];
    return true;
}
bool cmd_clr(macchina_t *m, const char *args) {
    char extra = '\0';
    if (sscanf(args, " %c", &extra) == 1) { return false; }
    memset(m->reg, 0, sizeof(m->reg));
    return true;
}
bool cmd_mov(macchina_t *m, const char *args) {
    int d = 0, s = 0; char extra = '\0';
    if (sscanf(args, "%d %d %c", &d, &s, &extra) != 2 || !reg_valido(d) || !reg_valido(s)) { return false; }
    m->reg[d] = m->reg[s];
    return true;
}
bool cmd_mul(macchina_t *m, const char *args) {
    int d = 0; long long k = 0; char extra = '\0';
    if (sscanf(args, "%d %lld %c", &d, &k, &extra) != 2 || !reg_valido(d)) { return false; }
    m->reg[d] *= (int64_t)k;
    return true;
}
bool cmd_set(macchina_t *m, const char *args) {
    int d = 0; long long v = 0; char extra = '\0';
    if (sscanf(args, "%d %lld %c", &d, &v, &extra) != 2 || !reg_valido(d)) { return false; }
    m->reg[d] = (int64_t)v;
    return true;
}
bool cmd_sub(macchina_t *m, const char *args) {
    int d = 0, s = 0; char extra = '\0';
    if (sscanf(args, "%d %d %c", &d, &s, &extra) != 2 || !reg_valido(d) || !reg_valido(s)) { return false; }
    m->reg[d] -= m->reg[s];
    return true;
}
bool cmd_swap(macchina_t *m, const char *args) {
    int a = 0, b = 0; char extra = '\0';
    if (sscanf(args, "%d %d %c", &a, &b, &extra) != 2 || !reg_valido(a) || !reg_valido(b)) { return false; }
    int64_t tmp = m->reg[a];
    m->reg[a] = m->reg[b];
    m->reg[b] = tmp;
    return true;
}

static const voce_cmd_t TABELLA_CMD[] = {
    {"ADD", cmd_add}, {"CLR", cmd_clr}, {"MOV", cmd_mov},
    {"MUL", cmd_mul}, {"SET", cmd_set}, {"SUB", cmd_sub}, {"SWAP", cmd_swap}
};

void stampa_dec(const macchina_t *m) {
    printf("Registri (DEC): R0=%" PRId64 " R1=%" PRId64 " R2=%" PRId64 " R3=%" PRId64 "\n",
           m->reg[0], m->reg[1], m->reg[2], m->reg[3]);
}
void stampa_hex(const macchina_t *m) {
    printf("Registri (HEX): R0=0x%016" PRIx64 " R1=0x%016" PRIx64 " R2=0x%016" PRIx64 " R3=0x%016" PRIx64 "\n",
           (uint64_t)m->reg[0], (uint64_t)m->reg[1], (uint64_t)m->reg[2], (uint64_t)m->reg[3]);
}
void stampa_somma(const macchina_t *m) {
    int64_t s = m->reg[0] + m->reg[1] + m->reg[2] + m->reg[3];
    printf("Somma registri: %" PRId64 "\n", s);
}

static const stampa_fn STAMPATORI[] = {stampa_dec, stampa_hex, stampa_somma};
static_assert(sizeof(STAMPATORI) / sizeof(STAMPATORI[0]) == FMT_CONTEGGIO,
              "STAMPATORI deve avere una voce per ogni formato_out_t");

int cmp_voce_cmd(const void *a, const void *b) {
    const voce_cmd_t *va = a;
    const voce_cmd_t *vb = b;
    return strcmp(va->nome, vb->nome);
}

int main(void) {
    char riga[256], extra = '\0';
    int fmt_in = 0;
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &fmt_in, &extra) != 1 || fmt_in < 0 || fmt_in >= FMT_CONTEGGIO) {
        fprintf(stderr, "Errore: formato di uscita non valido.\n");
        return EXIT_FAILURE;
    }
    size_t fmt = (size_t)fmt_in;
    constexpr size_t num_cmd = sizeof(TABELLA_CMD) / sizeof(TABELLA_CMD[0]);
    macchina_t m = {};
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        char nome[16];
        int letti = 0;
        if (sscanf(riga, "%15s%n", nome, &letti) != 1) { continue; }
        voce_cmd_t chiave = {.nome = nome, .esegui = nullptr};
        const voce_cmd_t *voce = bsearch(&chiave, TABELLA_CMD, num_cmd, sizeof(TABELLA_CMD[0]), cmp_voce_cmd);
        if (voce == nullptr || voce->esegui == nullptr) {
            printf("Comando sconosciuto: %s\n", nome);
        } else if (voce->esegui(&m, riga + letti)) {
            ++m.ops_eseguite;
        } else {
            printf("Argomenti non validi per %s\n", nome);
        }
    }
    if (fmt < FMT_CONTEGGIO && STAMPATORI[fmt] != nullptr) {
        STAMPATORI[fmt](&m);
    }
    printf("Operazioni eseguite: %zu\n", m.ops_eseguite);
    return EXIT_SUCCESS;
}
